const SLIM_EXT_GZ = '.json.gz';
    // 各维度参与内容哈希的字段（瘦身时**绝不删除**，同义字段保留的是这些）
    const SLIM_HASHED_FIELDS = {
        atoms: ['text', 'title', 'date', 'time', 'type', 'entities', 'locations', 'tags'],
        currentStates: ['subject', 'field', 'value', 'status'],
        snapshots: ['name', 'identity', 'appearance', 'personality', 'background', 'relationships', 'social', 'future'],
        memories: ['owner', 'date', 'title', 'content', 'memCategory', 'tags'],
        items: ['name', 'qty', 'desc', 'location', 'carried', 'tags'],
        plans: ['content', 'tags', 'status', 'planner', 'participants', 'steps', 'prereq', 'blockers', 'progress', 'history', 'phase', 'statusNote'],
        suspense: ['content', 'tags', 'status', 'clues', 'resolveCondition', 'level', 'history', 'phase', 'statusNote'],
        scenes: ['name', 'pathArr', 'desc'],
        concepts: ['name', 'content', 'source', 'date', 'tags'],
        parallels: ['title', 'text', 'date', 'gua', 'causalLine', 'characters', 'location', 'goalOdds', 'tags', 'promotedTo'],
        // v1.165：通用知情关联层（引用类字段不进哈希，但必须参与瘦身白名单/保留判断）
        links: ['dim', 'refId', 'who', 'how', 'from', 'at', 'view', 'deviation', 'note', 'kind', 'public'],
        // v1.191：情节分段总结（时间范围 + 逐条剧情线参与哈希；raw/atomIds/manual 不进）
        plotSegments: ['header', 'start', 'end', 'lines'],
        // v1.192：传言（主体 / 说法 / 客观性 / 阶段与发酵度 / 传播者 / 载体 / 传导链路 / 谱系 / 联动引用参与哈希）
        rumors: ['subject', 'content', 'objectivity', 'stage', 'ferment', 'carriers', 'media', 'chain', 'source', 'tags', 'parallelRefs', 'pending', 'lineage'],
    };
    // 同义字段组（组内只保留「哈希字段」那一份；仅当值完全一致时丢弃其它）
    const SLIM_SYNONYM_GROUPS = {
        atoms: [['text', 'content']],
        currentStates: [['value', 'content']],
        snapshots: [['name', 'title']],
        memories: [],
        items: [['desc', 'content']],
        plans: [],
        suspense: [],
        scenes: [['desc', 'content'], ['name', 'title'], ['pathArr', 'pathStr']],
        concepts: [['name', 'title']],
        parallels: [['text', 'content']],
        links: [],
        plotSegments: [['lines', 'items'], ['header', '时间范围'], ['header', 'title']],
        // v1.192：传言（主体 ↔ 标题同值时只留哈希字段）
        rumors: [['subject', 'title'], ['content', 'text']],
    };

v1SourceSnips.slimEntry:
function slimEntryForStorage(cat, it) {
        try {
            if (!it || typeof it !== 'object') return it;
            const hashed = SLIM_HASHED_FIELDS[cat] || [];
            const out = {};
            for (const f of Object.keys(it)) {
                if (f === 'extra') continue;                 // 单独处理
                if (isSlimDefault(it[f])) continue;          // 空值/默认值不写盘（读入由 migrate/哈希归一化兜底）
                out[f] = it[f];
            }
            // 同义字段：只留哈希字段那一份（值一致才丢）
            for (const grp of (SLIM_SYNONYM_GROUPS[cat] || [])) {
                const present = grp.filter(f => out[f] !== undefined);
                if (present.length < 2) continue;
                const keeper = present.find(f => hashed.includes(f)) || present[0];
                const kv = out[keeper];
                for (const f of present) {
                    if (f === keeper) continue;
                    const same = (f === 'pathStr' && Array.isArray(kv))
                        ? (String(out[f]) === kv.join('>'))
                        : (JSON.stringify(out[f]) === JSON.stringify(kv));
                    if (same) delete out[f];
                }
            }
            if (/\.json$/.test(String(out.name || ''))) delete out.name;   // 历史脏数据（把文件名写进了 name）
            // extra：只保留「顶层没有或值不同」的槽位（实测 94% 槽位是顶层字段的重复回显）
            if (Array.isArray(it.extra)) {
                const keep = it.extra.filter((s) => {
                    if (!s || typeof s !== 'object') return false;
                    const top = it[s.name];
                    return !(top !== undefined && JSON.stringify(top) === JSON.stringify(s.value));
                });
                if (keep.length) out.extra = keep;
            }
            return out;
        } catch (e) { return it; }
    }

v1SourceSnips.hydrateSlimEntry:
function hydrateSlimEntry(cat, it) {
        try {
            if (!it || typeof it !== 'object') return it;
            const hashed = SLIM_HASHED_FIELDS[cat] || [];
            for (const grp of (SLIM_SYNONYM_GROUPS[cat] || [])) {
                const present = grp.filter(f => it[f] !== undefined && it[f] !== null);
                if (!present.length) continue;
                const keeper = present.find(f => hashed.includes(f)) || present[0];
                for (const f of grp) {
                    if (f === keeper || it[f] !== undefined) continue;
                    if (f === 'pathStr' && Array.isArray(it[keeper])) it.pathStr = it[keeper].join('>');
                    else if (f === 'pathArr' && typeof it[keeper] === 'string') it.pathArr = String(it[keeper]).split('>');
                    else it[f] = it[keeper];
                }
            }
            // 显示层常同时读 name/title（即使不在同义组里）→ 缺一补一
            if (cat === 'scenes' || cat === 'snapshots' || cat === 'concepts' || cat === 'atoms' || cat === 'items' || cat === 'memories' || cat === 'plans' || cat === 'suspense' || cat === 'parallels' || cat === 'rumors') {
                if (it.name === undefined && it.title !== undefined) it.name = it.title;
                if (it.title === undefined && it.name !== undefined) it.title = it.name;
            }
            return it;
        } catch (e) { return it; }
    }

v1SourceSnips.slimData:
function slimDataForStorage(data, opts) {
        try {
            const o = Object.assign({}, data);
            if (!(opts && opts.keepSnap)) {
                o.snapIndex = snapshotIndexFrom(data.snapStore);
                delete o.snapStore;
                delete o.snapFp;
            }
            for (const cat of ATOM_DIM_KEYS) {
                if (Array.isArray(o[cat])) o[cat] = o[cat].map(it => slimEntryForStorage(cat, it));
            }
            delete o.scope;                 // 与信封 scope 重复
            return o;
        } catch (e) { return data; }
    }

v1SourceSnips.snapshotIndex:
function snapshotIndexFrom(snaps) {
        try {
            return (Array.isArray(snaps) ? snaps : []).map(s => ({
                id: s && s.id, kind: s && s.kind, ts: s && s.ts, baseId: s && s.baseId, hash: s && s.hash,
                covered: s && s.atomsHashes ? Object.keys(s.atomsHashes).length : 0,
            })).filter(x => x.id);
        } catch (e) { return []; }
    }

v1SourceSnips.slimSnapshot:
function slimSnapshotStoreForStorage(snaps) {
        try {
            return (Array.isArray(snaps) ? snaps : []).map(s => {
                const o = { id: s.id, kind: s.kind, ts: s.ts, baseId: s.baseId, hash: s.hash };
                if (s.atomsHashes) o.atomsHashes = s.atomsHashes;
                if (s.atoms) {
                    const a = {};
                    for (const id of Object.keys(s.atoms)) {
                        const atom = s.atoms[id];
                        const cat = (atom && atom.__cat) || 'atoms';
                        a[id] = slimEntryForStorage(cat, atom);
                    }
                    o.atoms = a;
                }
                if (s.deleted) o.deleted = s.deleted;
                return o;
            });
        } catch (e) { return snaps; }
    }

v1SourceSnips.gzip:
function bytesToBase64(u8) {
        try {
            let bin = '';
            const CH = 0x8000;
            for (let i = 0; i < u8.length; i += CH) bin += String.fromCharCode.apply(null, u8.subarray(i, i + CH));
            return btoa(bin);
        } catch (e) { return ''; }
    }
    function base64ToBytes(b64) {
        try {
            const bin = atob(String(b64 || '').replace(/\s+/g, ''));
            const u8 = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
            return u8;
        } catch (e) { return null; }
    }
    async function gzipToBase64(text) {
        try {
            if (typeof CompressionStream === 'function' && typeof Blob === 'function' && typeof Response === 'function') {
                const cs = new CompressionStream('gzip');
                const stream = new Blob([new TextEncoder().encode(String(text))]).stream().pipeThrough(cs);
                const buf = await new Response(stream).arrayBuffer();
                const b64 = bytesToBase64(new Uint8Array(buf));
                if (b64) return { ok: true, b64: b64 };
            }
        } catch (e) { }
        return { ok: false, b64: '' };
    }
    async function gunzipFromBytes(u8) {
        try {
            if (typeof DecompressionStream === 'function' && typeof Response === 'function') {
                const ds = new DecompressionStream('gzip');
                const stream = new Blob([u8]).stream().pipeThrough(ds);
                return await new Response(stream).text();
            }
        } catch (e) { }
        return null;
    }

v1SourceSnips.uploadContent:
async function filesUploadContent(baseName, text, timeoutMs) {
        fileCacheInvalidateBase(baseName);          // 写入后失效缓存（后续读取必须看到新内容）
        const gz = await gzipToBase64(text);
        if (gz.ok) {
            const r = await filesUploadBase64(baseName + SLIM_EXT_GZ, gz.b64, timeoutMs);
            if (r && r.ok) {
                // 写后即最新（缓存原文，后续读取不再重复下载；避免读到旧缓存导致重复上传）
                try { fileReadCache[baseName + SLIM_EXT_GZ] = { at: Date.now(), value: { text, gz: true } }; } catch (e) { }
                cleanupSupersededPlain(baseName);
                return Object.assign({}, r, { name: baseName + SLIM_EXT_GZ, gz: true });
            }
        }
        const r2 = await filesUploadText(baseName + '.json', text, timeoutMs);
        return Object.assign({}, r2 || { ok: false, reason: 'fail' }, { name: baseName + '.json', gz: false });
    }

v1SourceSnips.decodeBytes:
async function decodeFileBytes(name, u8, backend) {
        try {
            if (u8.length > 2 && u8[0] === 0x1f && u8[1] === 0x8b) {
                const t = await gunzipFromBytes(u8);
                if (t) readFilesThisSession[name] = Date.now();
                return t ? { text: t, gz: true, backend: backend, tt: backend === 'tt-native' } : null;
            }
            let t0 = '';
            try { t0 = new TextDecoder('utf-8').decode(u8); } catch (e) { t0 = ''; }
            if (!t0 || /^\s*[<]/.test(t0)) { fileReadOutcome[name] = 'invalid'; return null; }
            readFilesThisSession[name] = Date.now();
            return { text: t0, gz: false, backend: backend, tt: backend === 'tt-native' };
        } catch (e) { return null; }
    }

v1SourceSnips.slimFileEnvelope:
function slimFileEnvelope(env, keepSnap) {
        try {
            if (!env || !env.payload || !env.payload.data) return env;
            const data = slimDataForStorage(env.payload.data, { keepSnap: !!keepSnap });
            const payload = { scope: env.payload.scope, updatedAt: env.payload.updatedAt, data };
            return { v: env.v, scope: env.scope, payload, hash: storageHash(payload), ts: env.ts };
        } catch (e) { return env; }
    }

v1SourceSnips.fileNamesExts:
function fileNames(kind) {
        const out = [];
        const pushBase = (slug) => {
            if (!slug) return;
            // 先试 gz 再试明文（读取按魔数识别，两个扩展名都能读）
            // 日志文件只可能是明文（写入路径固定 filesUploadText）→ 不再探测 .json.gz
            const exts = (kind === 'log') ? ['.json'] : [SLIM_EXT_GZ, '.json'];
            exts.forEach(ext => { const n = fileNameFor(slug, kind, ext === '.json' ? 'json' : 'gz'); if (out.indexOf(n) < 0) out.push(n); });
        };
        pushBase(storageSlug());
        pushBase(slugFromName());
        pushBase(slugFallback());
        // 历史名（按 kind 过滤：state 的历史名里也含 bak/snap/log，用后缀/前缀区分）
        try {
            fileNameHistory().forEach((n) => { if (fileNameKindOf(n) === kind && out.indexOf(n) < 0) out.push(n); });
        } catch (e) { }
        return out;
    }
